class CobraFalso:
    """Imita la API de Cobrá. `falla` hace que todos los pedidos fallen: 'red' o 'error' (500)."""

    def __init__(self):
        self.pagos = {}
        self.por_clave = {}
        self.falla = None
        self.creados = 0
        self.pedidos = []

    def handler(self, request):
        if self.falla == 'red':
            raise httpx.ConnectError('conexión rechazada', request=request)
        if self.falla == 'error':
